"""Generate ledgerlite/_rates.py from data/rates.csv.

Usage: python3 scripts/gen_rates.py [--check]
--check exits 1 when the generated module is out of date.
"""

import csv
import hashlib
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SOURCE = os.path.join(ROOT, "data", "rates.csv")
TARGET = os.path.join(ROOT, "ledgerlite", "_rates.py")


def render():
    with open(SOURCE, "rb") as fh:
        raw = fh.read()
    rows = list(csv.DictReader(raw.decode("utf-8").splitlines()))
    lines = [
        "# GENERATED by scripts/gen_rates.py from data/rates.csv -- do not edit.",
        "# source-sha256: " + hashlib.sha256(raw).hexdigest(),
        "EUR_PER_UNIT = {",
    ]
    for row in sorted(rows, key=lambda r: r["currency"].strip().upper()):
        lines.append("    {!r}: {!r},".format(
            row["currency"].strip().upper(), float(row["eur_per_unit"])))
    lines.append("}")
    return "\n".join(lines) + "\n"


def main(argv):
    text = render()
    if "--check" in argv:
        try:
            with open(TARGET, encoding="utf-8") as fh:
                current = fh.read()
        except FileNotFoundError:
            current = ""
        if current != text:
            print("ledgerlite/_rates.py is out of date; run ./scripts/dev.sh gen",
                  file=sys.stderr)
            return 1
        return 0
    with open(TARGET, "w", encoding="utf-8") as fh:
        fh.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
